package com.saasquatch.intelligence.intelligence; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.dto.ScoreBreakdown; import java.util.*; public class OpportunityScoringEngine { public ScoreBreakdown breakdown(Lead l){Company c=l.getCompany(); int revenue=c.getEstimatedRevenueMillions()!=null?(c.getEstimatedRevenueMillions()>=100?20:c.getEstimatedRevenueMillions()>=25?15:10):8; int growth=c.getGrowthRate()!=null?(c.getGrowthRate()>=30?18:c.getGrowthRate()>=15?14:c.getGrowthRate()>0?8:3):5; int tech=contains(c.getTechnologyStack(),"spring")||contains(c.getTechnologyStack(),"react")||contains(c.getTechnologyStack(),"aws")?17:10; int dm=l.isDecisionMaker()?15:8; int industry=c.getIndustry()!=null&&List.of("SaaS","Software","Technology","FinTech").stream().anyMatch(x->x.equalsIgnoreCase(c.getIndustry()))?14:8; int corp=(int)Math.min(6,l.getSignals().stream().filter(s->s.getType()==SignalType.CORPORATE_RELATIONSHIP).mapToInt(BuyingSignal::getWeight).sum()); int conf=Math.max(0,Math.min(10,(l.getDataConfidence()==null?70:l.getDataConfidence())/10)); return new ScoreBreakdown(revenue,growth,tech,dm,industry,corp,conf);} private boolean contains(String s,String x){return s!=null&&s.toLowerCase().contains(x);} }